export function editorText(key) {
    return messages[key]?.[{ ko: 0, en: 1, ja: 2 }[getCurrentLanguage()] ?? 0] || messages.error[{ ko: 0, en: 1, ja: 2 }[getCurrentLanguage()] ?? 0];
}
